<script>
(function(){
"use strict";

/* ---------- Helpers ---------- */
var $  = function(s, c){ return (c || document).querySelector(s); };
var $$ = function(s, c){ return Array.prototype.slice.call((c || document).querySelectorAll(s)); };
var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/* ---------- Theme (default: dark) ---------- */
var root = document.documentElement;
var toggle = $("#themeToggle");
var metaTheme = $("#metaTheme");
var THEME_KEY = "ocean-theme";

function applyTheme(theme){
  root.setAttribute("data-theme", theme);
  var light = theme === "light";
  toggle.setAttribute("aria-pressed", String(light));
  toggle.setAttribute("aria-label", light ? "Switch to dark theme" : "Switch to light theme");
  metaTheme.setAttribute("content", light ? "#f2f9fb" : "#04101c");
}
(function initTheme(){
  var saved = null;
  try { saved = localStorage.getItem(THEME_KEY); } catch(e){}
  applyTheme(saved === "light" ? "light" : "dark");
})();
toggle.addEventListener("click", function(){
  var next = root.getAttribute("data-theme") === "light" ? "dark" : "light";
  applyTheme(next);
  try { localStorage.setItem(THEME_KEY, next); } catch(e){}
  if (window.__planktonRecolor) window.__planktonRecolor();
});

/* ---------- Mobile menu ---------- */
var menuBtn = $("#menuBtn");
var navLinks = $("#navLinks");
menuBtn.addEventListener("click", function(){
  var open = navLinks.classList.toggle("open");
  menuBtn.setAttribute("aria-expanded", String(open));
});
$$("#navLinks a").forEach(function(a){
  a.addEventListener("click", function(){
    navLinks.classList.remove("open");
    menuBtn.setAttribute("aria-expanded", "false");
  });
});

/* ---------- Header state + reading progress ---------- */
var header = $("#siteHeader");
var bar = $("#progressBar");
var ticking = false;
function onScroll(){
  var y = window.scrollY || document.documentElement.scrollTop;
  header.classList.toggle("scrolled", y > 10);
  var max = document.documentElement.scrollHeight - window.innerHeight;
  bar.style.width = (max > 0 ? Math.min(100, y / max * 100) : 0) + "%";
  ticking = false;
}
window.addEventListener("scroll", function(){
  if(!ticking){ requestAnimationFrame(onScroll); ticking = true; }
}, { passive:true });
onScroll();

/* ---------- Scrollspy ---------- */
var spyLinks = $$("#navLinks a[data-spy]");
var spyMap = {};
spyLinks.forEach(function(a){ spyMap[a.getAttribute("href").slice(1)] = a; });
var spySections = $$("[id]").filter(function(el){ return !!spyMap[el.id]; });
if ("IntersectionObserver" in window && spySections.length){
  var spyIO = new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      if (en.isIntersecting){
        spyLinks.forEach(function(a){ a.classList.remove("active"); });
        var link = spyMap[en.target.id];
        if (link) link.classList.add("active");
      }
    });
  }, { rootMargin: "-40% 0px -55% 0px" });
  spySections.forEach(function(s){ spyIO.observe(s); });
}

/* ---------- Reveal on scroll ---------- */
var revealEls = $$(".reveal");
if ("IntersectionObserver" in window && !reduceMotion){
  var revealIO = new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      if (en.isIntersecting){ en.target.classList.add("in"); revealIO.unobserve(en.target); }
    });
  }, { threshold: 0.12, rootMargin: "0px 0px -6% 0px" });
  revealEls.forEach(function(el){ revealIO.observe(el); });
} else {
  revealEls.forEach(function(el){ el.classList.add("in"); });
}

/* ---------- Count-up stats ---------- */
function animateCount(el){
  var target = parseFloat(el.getAttribute("data-count")) || 0;
  var suffix = el.getAttribute("data-suffix") || "";
  var dur = 1600, t0 = null;
  function fmt(n){ return Math.round(n).toLocaleString("en-US"); }
  if (reduceMotion){ el.textContent = fmt(target) + suffix; return; }
  function step(ts){
    if (!t0) t0 = ts;
    var p = Math.min(1, (ts - t0) / dur);
    var eased = 1 - Math.pow(1 - p, 3);
    el.textContent = fmt(target * eased) + suffix;
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
var counters = $$("[data-count]");
if ("IntersectionObserver" in window){
  var countIO = new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      if (en.isIntersecting){ animateCount(en.target); countIO.unobserve(en.target); }
    });
  }, { threshold: 0.4 });
  counters.forEach(function(c){ countIO.observe(c); });
} else {
  counters.forEach(animateCount);
}

/* ---------- Plankton canvas (hero) ---------- */
(function plankton(){
  var canvas = $("#plankton");
  if (!canvas || !canvas.getContext) return;
  var ctx = canvas.getContext("2d");
  var W = 0, H = 0, dpr = Math.min(window.devicePixelRatio || 1, 2);
  var parts = [], running = false, raf = 0;

  function colors(){
    var light = root.getAttribute("data-theme") === "light";
    var a = light ? "12,143,122" : "94,234,212";
    var b = light ? "11,116,184" : "96,201,257";
    var base = light ? 0.35 : 0.8;
    return [a, b, base];
  }
  function make(n){
    var c = colors();
    parts = [];
    for (var i = 0; i < n; i++){
      parts.push({
        x: Math.random() * W,
        y: Math.random() * H,
        r: 0.6 + Math.random() * 1.9,
        vy: 0.08 + Math.random() * 0.3,
        ph: Math.random() * Math.PI * 2,
        sw: 0.2 + Math.random() * 0.5,
        a: 0.15 + Math.random() * 0.5,
        tw: 0.5 + Math.random() * 2,
        c: Math.random() < 0.5 ? c[0] : c[1],
        base: c[2]
      });
    }
  }
  function resize(){
    var rect = canvas.parentElement.getBoundingClientRect();
    W = rect.width; H = rect.height;
    canvas.width = W * dpr; canvas.height = H * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    make(Math.max(24, Math.min(90, Math.floor(W * H / 16000))));
    if (reduceMotion) drawStatic();
  }
  function drawStatic(){
    ctx.clearRect(0, 0, W, H);
    parts.forEach(function(p){
      ctx.beginPath();
      ctx.fillStyle = "rgba(" + p.c + "," + (p.a * p.base) + ")";
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    });
  }
  function frame(t){
    if (!running) return;
    ctx.clearRect(0, 0, W, H);
    for (var i = 0; i < parts.length; i++){
      var p = parts[i];
      p.y -= p.vy;
      p.x += Math.sin(t / 1400 + p.ph) * p.sw * 0.15;
      if (p.y < -6){ p.y = H + 6; p.x = Math.random() * W; }
      if (p.x < -6) p.x = W + 6;
      if (p.x > W + 6) p.x = -6;
      var tw = 0.6 + 0.4 * Math.sin(t / 700 * p.tw + p.ph);
      ctx.beginPath();
      ctx.fillStyle = "rgba(" + p.c + "," + (p.a * p.base * tw) + ")";
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
    raf = requestAnimationFrame(frame);
  }
  window.__planktonRecolor = function(){
    make(parts.length ? parts.length : 40);
    if (reduceMotion) drawStatic();
  };

  resize();
  window.addEventListener("resize", resize);
  if (!reduceMotion){
    document.addEventListener("visibilitychange", function(){
      if (document.hidden){ running = false; cancelAnimationFrame(raf); }
      else if (!running){ running = true; raf = requestAnimationFrame(frame); }
    });
    running = true;
    raf = requestAnimationFrame(frame);
  }
})();

/* ---------- Depth explorer ---------- */
(function depth(){
  var zones = [
    { name:"Sunlight Zone",  lat:"Epipelagic",    range:"0–200 m",        rep:100,  temp:"~20 °C",   light:"100 → 1%", pres:"~21 atm",
      desc:"Sunlit, warm and crowded: nearly all coral reefs and the bulk of marine life live here, built on phytoplankton that turn light into the base of the food web." },
    { name:"Twilight Zone",  lat:"Mesopelagic",   range:"200–1,000 m",    rep:600,  temp:"4–8 °C",   light:"< 1%",     pres:"~101 atm",
      desc:"Light fades to the faintest blue. Each night the largest migration on Earth passes through here as billions of lanternfish rise to feed." },
    { name:"Midnight Zone",  lat:"Bathypelagic",  range:"1,000–4,000 m",  rep:2500, temp:"2–4 °C",   light:"0%",       pres:"~401 atm",
      desc:"No sunlight has ever reached here. Bioluminescence becomes language, lure and weapon — most animals make their own light." },
    { name:"The Abyss",      lat:"Abyssopelagic", range:"4,000–6,000 m",  rep:5000, temp:"~2 °C",    light:"0%",       pres:"~601 atm",
      desc:"Vast, cold plains of soft sediment — the single largest habitat on Earth, alive with ghostly denizens that drift on the marine snow." },
    { name:"The Trenches",   lat:"Hadalpelagic",  range:"6,000–11,000 m", rep:8500, temp:"1–2 °C",   light:"0%",       pres:"~1,100 atm",
      desc:"Crush pressure and near-freezing water in Earth's deepest scars — yet even here, in the hadal zone, translucent life endures." }
  ];
  var MAXD = 11000;
  var btns = $$(".zone-btn");
  var marker = $("#depthMarker");
  var roName = $("#roName"), roLat = $("#roLat"), roDesc = $("#roDesc"),
      roDepth = $("#roDepth"), roTemp = $("#roTemp"), roLight = $("#roLight"), roPres = $("#roPres");

  function select(i){
    var z = zones[i];
    btns.forEach(function(b, j){
      b.classList.toggle("active", j === i);
      b.setAttribute("aria-selected", String(j === i));
    });
    marker.style.top = (z.rep / MAXD * 100).toFixed(2) + "%";
    roName.textContent  = z.name;
    roLat.textContent   = z.lat;
    roDesc.textContent  = z.desc;
    roDepth.textContent = z.range;
    roTemp.textContent  = z.temp;
    roLight.textContent = z.light;
    roPres.textContent  = z.pres;
  }
  btns.forEach(function(b){
    b.addEventListener("click", function(){ select(parseInt(b.getAttribute("data-zone"), 10)); });
  });
  select(0);
})();

/* ---------- Subscribe form (demo) ---------- */
(function form(){
  var form = $("#subscribeForm");
  if (!form) return;
  var nameField = $("#nameField"), emailField = $("#emailField");
  var success = $("#formSuccess");
  form.addEventListener("submit", function(e){
    e.preventDefault();
    var nameOk = $("#fName").value.trim().length > 0;
    var emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test($("#fEmail").value.trim());
    nameField.classList.toggle("invalid", !nameOk);
    emailField.classList.toggle("invalid", !emailOk);
    if (!nameOk){ $("#fName").focus(); return; }
    if (!emailOk){ $("#fEmail").focus(); return; }
    form.style.display = "none";
    success.classList.add("show");
  });
  ["fName","fEmail"].forEach(function(id){
    var input = $("#" + id);
    input.addEventListener("input", function(){
      input.closest(".field").classList.remove("invalid");
    });
  });
})();

/* ---------- Footer year ---------- */
$("#year").textContent = new Date().getFullYear();

})();
</script>
</body>
